-- ES/DE/FR translations for the rest of Spain's deep-dive content.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Doble vía — VeriFactu + Crea y Crece', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La orden ministerial de desarrollo de Crea y Crece sigue sin publicarse en el momento de escribir esto, lo que significa que el formato B2B y las fechas exactas aún podrían cambiar — confirme los requisitos actuales directamente con la Agencia Tributaria antes de construir una integración.', 'Tres regímenes distintos — B2G, SII y ahora VeriFactu — se han ido acumulando a lo largo de más de una década. El mandato B2B de Crea y Crece es la pieza más reciente, y la que todavía carece de su detalle de desarrollo.', 'Lo más importante que hay que entender sobre España: VeriFactu no es en absoluto un formato de factura — es un requisito sobre el software que produce sus facturas.', 'España ejecuta dos reformas separadas y complementarias que es fácil confundir: VeriFactu asegura el propio software de facturación (fechas confirmadas, enero/julio de 2027), mientras que Crea y Crece exige el intercambio estructurado de facturas B2B (ley marco aprobada, pero la orden ministerial de desarrollo — y por tanto las fechas exactas de inicio — sigue pendiente a mediados de 2026). Más allá de esa distinción, España ejecuta tres sistemas paralelos que no se comunican todos de la misma manera — saber cuál se le aplica importa tanto como el detalle técnico.', 'Dado que dos reformas avanzan por vías diferentes, su lista de preparación se divide genuinamente en dos.', 'La estructura de sanciones de España escala con la gravedad del problema subyacente — un desliz de formato y el fraude puro se sitúan en extremos opuestos de un rango muy amplio.' FROM countries WHERE name_en = 'Spain';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zweigleisig — VeriFactu + Crea y Crece', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Durchführungsverordnung zu Crea y Crece war zum Zeitpunkt der Erstellung noch nicht veröffentlicht, sodass sich B2B-Format und genaue Termine noch ändern könnten — bestätigen Sie aktuelle Anforderungen direkt bei der Agencia Tributaria, bevor Sie eine Integration aufbauen.', 'Drei unterschiedliche Regime — B2G, SII und nun VeriFactu — haben sich über mehr als ein Jahrzehnt angesammelt. Die B2B-Vorgabe von Crea y Crece ist das neueste Element und dasjenige, dem noch die Durchführungsdetails fehlen.', 'Das Wichtigste, was es über Spanien zu verstehen gilt: VeriFactu ist überhaupt kein Rechnungsformat — es ist eine Anforderung an die Software, die Ihre Rechnungen erzeugt.', 'Spanien betreibt zwei separate, sich ergänzende Reformen, die leicht verwechselt werden: VeriFactu sichert die Rechnungssoftware selbst ab (bestätigte Termine, Januar/Juli 2027), während Crea y Crece den strukturierten B2B-Rechnungsaustausch vorschreibt (Rahmengesetz verabschiedet, doch die Durchführungsverordnung des Ministeriums — und damit die genauen Startdaten — steht Mitte 2026 noch aus). Über diese Unterscheidung hinaus betreibt Spanien drei parallele Systeme, die nicht alle auf dieselbe Weise miteinander kommunizieren — zu wissen, welches für Sie gilt, ist ebenso wichtig wie das technische Detail.', 'Da zwei Reformen auf unterschiedlichen Schienen verlaufen, teilt sich Ihre Checkliste zur Vorbereitung genuin in zwei.', 'Spaniens Sanktionsstruktur skaliert mit der Schwere des zugrunde liegenden Problems — ein Formatierungsfehler und offener Betrug liegen an entgegengesetzten Enden einer sehr weiten Spanne.' FROM countries WHERE name_en = 'Spain';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Double voie — VeriFactu + Crea y Crece', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. L''arrêté ministériel d''application de Crea y Crece reste non publié au moment de la rédaction, ce qui signifie que le format B2B et les dates exactes pourraient encore changer — confirmez les exigences actuelles directement auprès de l''Agencia Tributaria avant de construire une intégration.', 'Trois régimes distincts — B2G, SII et désormais VeriFactu — se sont accumulés sur plus d''une décennie. L''obligation B2B de Crea y Crece est l''élément le plus récent, et celui auquel il manque encore le détail d''application.', 'L''élément le plus important à comprendre sur l''Espagne : VeriFactu n''est pas du tout un format de facture — c''est une exigence portant sur le logiciel qui produit vos factures.', 'L''Espagne mène deux réformes distinctes et complémentaires qu''il est facile de confondre : VeriFactu sécurise le logiciel de facturation lui-même (dates confirmées, janvier/juillet 2027), tandis que Crea y Crece impose l''échange structuré de factures B2B (loi-cadre adoptée, mais l''arrêté ministériel d''application — et donc les dates de démarrage exactes — reste en attente à la mi-2026). Au-delà de cette distinction, l''Espagne exploite trois systèmes parallèles qui ne communiquent pas tous de la même manière — savoir lequel s''applique à vous compte autant que le détail technique.', 'Deux réformes avançant sur des voies différentes, votre liste de préparation se divise véritablement en deux.', 'La structure de sanctions espagnole s''échelonne selon la gravité du problème sous-jacent — une erreur de format et une fraude pure se situent aux extrémités opposées d''un éventail très large.' FROM countries WHERE name_en = 'Spain';

