INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'VeriFactu (RRSIF) — un requisito de software, no un formato', '[["Qué regula", "El sistema de facturación (SIF), no el formato del archivo de la factura"], ["Mecanismos principales", "Registros encadenados por hash, firma digital, sello de tiempo seguro"], ["Marca visible", "Código QR + leyenda \"VERI*FACTU\" o equivalente"]]', 'Una factura conforme con VeriFactu puede seguir siendo, en apariencia, un PDF sencillo — lo que importa es la integridad del registro subyacente, no su formato visual.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'VeriFactu (RRSIF) — a software requirement, not a format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'VeriFactu (RRSIF) — eine Softwareanforderung, kein Format', '[["Was es regelt", "Das Rechnungssystem (SIF), nicht das Dateiformat der Rechnung"], ["Kernmechanismen", "Hash-verkettete Datensätze, digitale Signatur, sicherer Zeitstempel"], ["Sichtbares Kennzeichen", "QR-Code + Vermerk \"VERI*FACTU\" oder gleichwertig"]]', 'Eine VeriFactu-konforme Rechnung kann optisch weiterhin ein einfaches PDF sein — entscheidend ist die Integrität des zugrunde liegenden Datensatzes, nicht sein visuelles Format.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'VeriFactu (RRSIF) — a software requirement, not a format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'VeriFactu (RRSIF) — une exigence logicielle, pas un format', '[["Ce qu''il régit", "Le système de facturation (SIF), pas le format de fichier de la facture"], ["Mécanismes principaux", "Registres chaînés par hachage, signature numérique, horodatage sécurisé"], ["Marqueur visible", "Code QR + mention « VERI*FACTU » ou équivalent"]]', 'Une facture conforme à VeriFactu peut rester, en apparence, un simple PDF — ce qui compte est l''intégrité du registre sous-jacent, pas son format visuel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'VeriFactu (RRSIF) — a software requirement, not a format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato B2G (ya obligatorio)', '[["Formato", "Facturae 3.2.1 o 3.2.2"], ["Firma", "Se requiere certificado cualificado"], ["Entrega", "A través de FACe (o FACeB2B para cadenas de contratación)"]]', 'Esto lleva vigente más de una década y no está cambiando — trátelo como la base estable mientras VeriFactu y Crea y Crece siguen desarrollándose.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'B2G format (already mandatory)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2G-Format (bereits verpflichtend)', '[["Format", "Facturae 3.2.1 oder 3.2.2"], ["Signatur", "Qualifiziertes Zertifikat erforderlich"], ["Übermittlung", "Über FACe (oder FACeB2B für Beschaffungsketten)"]]', 'Dies gilt seit über einem Jahrzehnt und ändert sich nicht — behandeln Sie es als stabile Grundlage, während sich VeriFactu und Crea y Crece beide weiterentwickeln.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'B2G format (already mandatory)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format B2G (déjà obligatoire)', '[["Format", "Facturae 3.2.1 ou 3.2.2"], ["Signature", "Certificat qualifié requis"], ["Livraison", "Via FACe (ou FACeB2B pour les chaînes d''approvisionnement public)"]]', 'Ceci est en vigueur depuis plus d''une décennie et ne change pas — traitez-le comme la base stable pendant que VeriFactu et Crea y Crece continuent tous deux d''évoluer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'B2G format (already mandatory)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato B2B (Crea y Crece, pendiente)', '[["Formatos previstos", "Facturae y/o estándares compatibles con UBL"], ["Requisito confirmado", "Validación de contenido conforme a EN 16931"], ["Estado", "Formato final no fijado hasta que se publique la orden ministerial"]]', 'No incorpore todavía una suposición de esquema B2B específico en sistemas de producción — Facturae y UBL son ambos plausibles, y la orden lo determinará.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'B2B format (Crea y Crece, pending)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2B-Format (Crea y Crece, ausstehend)', '[["Erwartete Formate", "Facturae und/oder UBL-kompatible Standards"], ["Bestätigte Anforderung", "EN-16931-Inhaltsvalidierung"], ["Status", "Endgültiges Format erst nach Veröffentlichung der Ministerialverordnung festgelegt"]]', 'Bauen Sie noch keine konkrete B2B-Schema-Annahme in Produktivsysteme ein — sowohl Facturae als auch UBL sind plausibel, und die Verordnung wird dies festlegen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'B2B format (Crea y Crece, pending)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format B2B (Crea y Crece, en attente)', '[["Formats attendus", "Facturae et/ou normes compatibles UBL"], ["Exigence confirmée", "Validation du contenu conforme à l''EN 16931"], ["Statut", "Format final non arrêté avant la publication de l''arrêté ministériel"]]', 'Ne figez pas encore une hypothèse de schéma B2B spécifique dans les systèmes de production — Facturae et UBL sont tous deux plausibles, et l''arrêté tranchera.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'B2B format (Crea y Crece, pending)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Declaración de software (SIF)', '[["Requisito", "Declaración responsable presentada ante la AEAT"], ["Presentada por", "El desarrollador del software, no la empresa usuaria final"], ["Debe ser visible", "En el propio sistema, por versión, desde el momento de la compra"]]', 'Si usted es una empresa y no un proveedor de software, su tarea es confirmar que su proveedor ha presentado esta declaración — no presentarla usted mismo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'Software declaration (SIF)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Softwareerklärung (SIF)', '[["Anforderung", "Bei der AEAT eingereichte Eigenerklärung (declaración responsable)"], ["Eingereicht von", "Dem Softwareentwickler, nicht dem Endnutzerunternehmen"], ["Muss sichtbar sein", "Im System selbst, je Version, ab dem Kaufzeitpunkt"]]', 'Wenn Sie ein Unternehmen und kein Softwareanbieter sind, besteht Ihre Aufgabe darin zu bestätigen, dass Ihr Anbieter diese Erklärung eingereicht hat — nicht sie selbst einzureichen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'Software declaration (SIF)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Déclaration logicielle (SIF)', '[["Exigence", "Déclaration responsable déposée auprès de l''AEAT"], ["Déposée par", "L''éditeur du logiciel, pas l''entreprise utilisatrice finale"], ["Doit être visible", "Dans le système lui-même, par version, dès l''achat"]]', 'Si vous êtes une entreprise plutôt qu''un éditeur de logiciel, votre tâche consiste à confirmer que votre fournisseur a déposé cette déclaration — pas à la déposer vous-même.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'file_format' AND dct.title = 'Software declaration (SIF)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'SII frente a VeriFactu', '[["Alcance del SII", "Grandes contribuyentes, declarantes mensuales"], ["Cadencia del SII", "Reporte de libros registro en 4 días"], ["Alcance de VeriFactu", "Todos los demás que usan software de facturación"]]', 'Son mutuamente excluyentes — si está en el SII, queda explícitamente fuera del alcance de VeriFactu. No construya para ambos.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'SII vs. VeriFactu';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'SII gegenüber VeriFactu', '[["SII-Anwendungsbereich", "Großsteuerzahler, monatliche Melder"], ["SII-Rhythmus", "Registermeldung innerhalb von 4 Tagen"], ["VeriFactu-Anwendungsbereich", "Alle übrigen, die Rechnungssoftware nutzen"]]', 'Diese schließen sich gegenseitig aus — wenn Sie im SII sind, sind Sie ausdrücklich nicht vom Anwendungsbereich von VeriFactu erfasst. Bauen Sie nicht für beide.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'SII vs. VeriFactu';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'SII contre VeriFactu', '[["Champ d''application du SII", "Grands contribuables, déclarants mensuels"], ["Cadence du SII", "Déclaration des registres sous 4 jours"], ["Champ d''application de VeriFactu", "Tous les autres utilisant un logiciel de facturation"]]', 'Ils s''excluent mutuellement — si vous relevez du SII, vous êtes explicitement hors du champ de VeriFactu. Ne construisez pas pour les deux.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'SII vs. VeriFactu';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Los dos modos de VeriFactu', '[["Modo A", "Transmisión en tiempo real a la AEAT"], ["Modo B", "Almacenamiento local bajo estrictos requisitos de cadena de hash/auditoría"]]', 'Ambos modos satisfacen el requisito legal — la elección depende de su preferencia operativa entre el reporte en vivo y los registros locales conservados y a prueba de manipulación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'VeriFactu''s two modes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Die beiden Modi von VeriFactu', '[["Modus A", "Echtzeitübermittlung an die AEAT"], ["Modus B", "Lokale Speicherung unter strengen Hash-Ketten-/Prüfanforderungen"]]', 'Beide Modi erfüllen die gesetzliche Anforderung — die Wahl hängt von Ihrer betrieblichen Präferenz zwischen Live-Meldung und aufbewahrten, manipulationssicheren lokalen Aufzeichnungen ab.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'VeriFactu''s two modes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Les deux modes de VeriFactu', '[["Mode A", "Transmission en temps réel à l''AEAT"], ["Mode B", "Stockage local selon des exigences strictes de chaîne de hachage/audit"]]', 'Les deux modes satisfont l''exigence légale — le choix dépend de votre préférence opérationnelle entre la déclaration en direct et des registres locaux conservés et inviolables.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'VeriFactu''s two modes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Red de Crea y Crece (detalle pendiente)', '[["Opción pública", "Plataforma estatal, que recibe una \"copia fiel\""], ["Opción privada", "Operadores privados conectados"], ["Estado", "El modelo de red completo aún debe ser finalizado por la orden ministerial"]]', 'La red de facturación electrónica B2B no envía el contenido de la factura a la AEAT como sí puede hacerlo VeriFactu — es una capa separada de intercambio y seguimiento de estado entre las partes comerciales.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'Crea y Crece network (pending detail)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Crea-y-Crece-Netzwerk (Detail ausstehend)', '[["Öffentliche Option", "Staatliche Plattform, erhält eine \"copia fiel\" (originalgetreue Kopie)"], ["Private Option", "Angebundene private Betreiber"], ["Status", "Vollständiges Netzwerkmodell noch von der Ministerialverordnung festzulegen"]]', 'Das B2B-E-Invoicing-Netzwerk sendet Rechnungsinhalte nicht wie VeriFactu an die AEAT — es handelt sich um eine separate Austausch- und Statusverfolgungsebene zwischen Handelspartnern.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'Crea y Crece network (pending detail)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Réseau Crea y Crece (détail en attente)', '[["Option publique", "Plateforme d''État, recevant une « copia fiel » (copie fidèle)"], ["Option privée", "Opérateurs privés connectés"], ["Statut", "Le modèle de réseau complet reste à finaliser par l''arrêté ministériel"]]', 'Le réseau de facturation électronique B2B n''envoie pas le contenu des factures à l''AEAT comme le fait VeriFactu — il s''agit d''une couche distincte d''échange et de suivi de statut entre partenaires commerciaux.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'Crea y Crece network (pending detail)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Facultades de inspección de la AEAT', '[["Acceso", "Acceso total e inmediato a los datos del SIF a solicitud"], ["Facultades in situ", "Puede personarse donde se ubique/use el sistema"], ["Acciones disponibles", "Descargar, volcar, consultar o copiar datos directamente"]]', 'Se trata de una facultad de inspección considerablemente más fuerte que la que otorgan la mayoría de los regímenes de facturación electrónica de la UE — planifique la arquitectura de su sistema asumiendo que la AEAT puede y va a ejercerla.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'AEAT''s audit powers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Prüfungsbefugnisse der AEAT', '[["Zugriff", "Vollständiger, sofortiger Zugriff auf SIF-Daten auf Anfrage"], ["Vor-Ort-Befugnisse", "Kann dort erscheinen, wo das System sich befindet/genutzt wird"], ["Verfügbare Maßnahmen", "Herunterladen, Abziehen, Einsehen oder direktes Kopieren von Daten"]]', 'Dies ist eine deutlich stärkere Prüfungsbefugnis, als sie die meisten E-Invoicing-Regime der EU gewähren — planen Sie Ihre Systemarchitektur unter der Annahme, dass die AEAT sie ausüben kann und wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'AEAT''s audit powers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Pouvoirs d''audit de l''AEAT', '[["Accès", "Accès complet et immédiat aux données SIF sur demande"], ["Pouvoirs sur site", "Peut se présenter là où le système est situé/utilisé"], ["Actions disponibles", "Télécharger, extraire, consulter ou copier directement les données"]]', 'Il s''agit d''un pouvoir d''inspection nettement plus fort que celui accordé par la plupart des régimes de facturation électronique de l''UE — planifiez l''architecture de votre système en supposant que l''AEAT peut et va l''exercer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'scope_transmission' AND dct.title = 'AEAT''s audit powers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Los proveedores de software asumen un riesgo real', NULL, NULL, 'La sanción de 150.000 €/año por software no conforme se aplica al proveedor, no solo al usuario final — un fuerte incentivo para que los desarrolladores de SIF españoles obtengan la certificación RRSIF de forma genuinamente correcta en lugar de tomar atajos.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Software providers carry real exposure';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Softwareanbieter tragen echtes Risiko', NULL, NULL, 'Das Bußgeld von 150.000 €/Jahr für nicht konforme Software gilt für den Anbieter, nicht nur für den Endnutzer — ein starker Anreiz für spanische SIF-Entwickler, die RRSIF-Zertifizierung echt korrekt zu erlangen, statt Abkürzungen zu nehmen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Software providers carry real exposure';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Les éditeurs de logiciels portent un risque réel', NULL, NULL, 'L''amende de 150 000 €/an pour logiciel non conforme s''applique à l''éditeur, pas seulement à l''utilisateur final — une forte incitation pour les développeurs de SIF espagnols à obtenir la certification RRSIF véritablement correctement plutôt que de prendre des raccourcis.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Software providers carry real exposure';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔀 Dos reformas, dos panoramas de aplicación', NULL, NULL, 'Las sanciones de VeriFactu están confirmadas y ligadas a fechas firmes de 2027; el detalle de aplicación de Crea y Crece solo quedará claro una vez que se publique su orden ministerial — no asuma que se aplica la misma estructura de multas a ambas.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '🔀 Two reforms, two enforcement pictures';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔀 Zwei Reformen, zwei Durchsetzungsbilder', NULL, NULL, 'Die Sanktionen von VeriFactu sind bestätigt und an feste Termine 2027 gebunden; das Durchsetzungsdetail von Crea y Crece wird erst mit Veröffentlichung seiner Ministerialverordnung klar — gehen Sie nicht davon aus, dass für beide dieselbe Bußgeldstruktur gilt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '🔀 Two reforms, two enforcement pictures';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔀 Deux réformes, deux tableaux d''application', NULL, NULL, 'Les sanctions de VeriFactu sont confirmées et liées à des dates fermes de 2027 ; le détail d''application de Crea y Crece ne deviendra clair qu''une fois son arrêté ministériel publié — ne présumez pas que la même structure d''amendes s''applique aux deux.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '🔀 Two reforms, two enforcement pictures';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 Más allá de las multas', NULL, NULL, 'La facultad de la AEAT de exigir acceso total e inmediato a su sistema SIF significa que el riesgo de incumplimiento se extiende mucho más allá de las sanciones económicas, hasta la disrupción operativa directa durante una inspección.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '📋 Beyond fines';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 Jenseits von Bußgeldern', NULL, NULL, 'Die Befugnis der AEAT, sofortigen, vollständigen Zugriff auf Ihr SIF-System zu verlangen, bedeutet, dass das Nichteinhaltungsrisiko weit über finanzielle Sanktionen hinausgeht bis hin zu direkter betrieblicher Störung während einer Prüfung.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '📋 Beyond fines';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Au-delà des amendes', NULL, NULL, 'Le pouvoir de l''AEAT d''exiger un accès complet et immédiat à votre système SIF signifie que le risque de non-conformité s''étend bien au-delà des sanctions financières, jusqu''à une perturbation opérationnelle directe lors d''un contrôle.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Spain' AND dc.section = 'penalties_related' AND dct.title = '📋 Beyond fines';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Determine su régimen: SII o VeriFactu', 'Compruebe si ya es un gran contribuyente o declarante mensual dentro del SII — si es así, VeriFactu no se le aplica en absoluto.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Determine your regime: SII or VeriFactu';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestimmen Sie Ihr Regime: SII oder VeriFactu', 'Prüfen Sie, ob Sie bereits ein Großsteuerzahler oder monatlicher Melder im SII sind — falls ja, gilt VeriFactu für Sie überhaupt nicht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Determine your regime: SII or VeriFactu';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déterminez votre régime : SII ou VeriFactu', 'Vérifiez si vous êtes déjà un grand contribuable ou déclarant mensuel dans le SII — si oui, VeriFactu ne s''applique pas du tout à vous.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Determine your regime: SII or VeriFactu';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme la declaración ante la AEAT de su proveedor de software', 'Pida a su proveedor de software de facturación que confirme que ha presentado la declaración responsable para su versión específica — es su obligación, no la suya, pero usted necesita la garantía.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Confirm your software vendor''s AEAT declaration';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie die AEAT-Erklärung Ihres Softwareanbieters', 'Bitten Sie Ihren Rechnungssoftware-Anbieter, zu bestätigen, dass er die Eigenerklärung für Ihre spezifische Version eingereicht hat — dies ist seine Pflicht, nicht Ihre, doch Sie benötigen die Zusicherung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Confirm your software vendor''s AEAT declaration';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez la déclaration AEAT de votre éditeur de logiciel', 'Demandez à votre fournisseur de logiciel de facturation de confirmer qu''il a déposé la déclaration responsable pour votre version spécifique — c''est son obligation, pas la vôtre, mais vous avez besoin de cette assurance.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Confirm your software vendor''s AEAT declaration';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su modo de VeriFactu antes de su plazo', 'Contribuyentes corporativos: decidan entre transmisión en tiempo real a la AEAT o almacenamiento local con cadena de hash antes del 1 de enero de 2027. Autónomos y otros: la misma decisión se aplica antes del 1 de julio de 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Choose your VeriFactu mode ahead of your deadline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren VeriFactu-Modus vor Ihrer Frist', 'Körperschaftsteuerpflichtige: Entscheiden Sie sich vor dem 1. Januar 2027 zwischen Echtzeitübermittlung an die AEAT und lokaler hashverketteter Speicherung. Autónomos und andere: Dieselbe Entscheidung gilt vor dem 1. Juli 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Choose your VeriFactu mode ahead of your deadline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre mode VeriFactu avant votre échéance', 'Contribuables soumis à l''IS : décidez entre transmission en temps réel à l''AEAT et stockage local à chaîne de hachage avant le 1er janvier 2027. Indépendants et autres : la même décision s''applique avant le 1er juillet 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Choose your VeriFactu mode ahead of your deadline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Mantenga actualizado su canal B2G', 'Si ya factura a organismos públicos, confirme que la generación de Facturae 3.2.1/3.2.2 y el envío a través de FACe siguen funcionando correctamente — esta obligación no está cambiando.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Keep your B2G channel current';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Halten Sie Ihren B2G-Kanal aktuell', 'Wenn Sie bereits öffentliche Stellen fakturieren, bestätigen Sie, dass die Facturae-3.2.1/3.2.2-Erzeugung und die FACe-Einreichung weiterhin einwandfrei funktionieren — diese Pflicht ändert sich nicht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Keep your B2G channel current';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Maintenez votre canal B2G à jour', 'Si vous facturez déjà des organismes publics, confirmez que la génération Facturae 3.2.1/3.2.2 et la soumission via FACe restent en bon état de fonctionnement — cette obligation ne change pas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Keep your B2G channel current';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Esté atento a la orden ministerial de Crea y Crece', 'Una vez publicada, su plazo de cumplimiento comienza de inmediato — 1 año si supera los 8 millones € de facturación, 2 años en caso contrario. No espere a la publicación para empezar a evaluar plataformas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Watch for the Crea y Crece ministerial order';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Achten Sie auf die Crea-y-Crece-Ministerialverordnung', 'Nach Veröffentlichung beginnt Ihre Compliance-Frist sofort — 1 Jahr bei über 8 Millionen € Umsatz, sonst 2 Jahre. Warten Sie nicht auf die Veröffentlichung, um mit der Plattformbewertung zu beginnen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Watch for the Crea y Crece ministerial order';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez l''arrêté ministériel Crea y Crece', 'Une fois publié, votre délai de conformité démarre immédiatement — 1 an au-delà de 8 millions € de chiffre d''affaires, 2 ans sinon. N''attendez pas la publication pour commencer à évaluer les plateformes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Watch for the Crea y Crece ministerial order';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure un archivo de doble vía', 'Planifique por separado la conservación fiscal de 4 años y la conservación mercantil de 6 años, y notifique a la AEAT si algún registro se aloja en el extranjero.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Set up dual-track archiving';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine zweigleisige Archivierung ein', 'Planen Sie die 4-jährige steuerliche und die 6-jährige handelsrechtliche Aufbewahrung getrennt, und melden Sie der AEAT, falls Aufzeichnungen im Ausland gehostet werden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Set up dual-track archiving';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage à double voie', 'Planifiez séparément la conservation fiscale de 4 ans et la conservation commerciale de 6 ans, et informez l''AEAT si des registres sont hébergés à l''étranger.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Spain' AND dst.title = 'Set up dual-track archiving';

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Agencia Tributaria — VeriFactu' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Spain';
